import test from 'node:test';import assert from 'node:assert/strict';
import {action,settle,summary,investmentAccount,CATALOG,DAY} from '../src/engine.mjs';import {compoundProjection} from '../src/learning.mjs';
const now=Date.parse('2026-10-31T12:00Z'),market={prices:Object.fromEntries(CATALOG.map(c=>[c.id,{eur:100,local:100,currency:'USD',at:now-DAY,fetchedAt:now}])),rate:{annualPct:2.4,date:'2026-10-30',fetchedAt:now},events:[]};const run=(s,a,t=now,m=market)=>action(s,m,{requestId:crypto.randomUUID(),...a},t,{parent:true});
function create(){let s=run(null,{type:'open_account',name:'Test'});s=run(s,{type:'setup',config:{experience:'investing',salary:10,initial:2}});return run(s,{type:'receive'})}
test('exactly 20 real companies; Waymo is represented by Alphabet, plus four funds',()=>{assert.equal(CATALOG.filter(c=>c.group==='stocks').length,20);assert.equal(CATALOG.filter(c=>['funds','bonds'].includes(c.group)).length,4);assert.equal(new Set(CATALOG.map(c=>c.id)).size,CATALOG.length);assert.equal(CATALOG.some(c=>c.id==='WAYMO'),false);assert.match(CATALOG.find(c=>c.id==='GOOGL').what,/Waymo/);for(const c of CATALOG.filter(c=>c.group==='stocks'))for(const key of ['what','value','up','down','source'])assert.ok(c[key]);});
test('monthly allowances are idempotent and produce no household bills or reserve',()=>{const s=create();assert.equal(s.cash,1000000);assert.equal(s.config.reserve,0);assert.equal(s.bills.length,0);const next=settle(s,market,now+365*DAY);assert.equal(next.months.length,12);assert.equal(next.bills.length,0);assert.equal(next.cash,1120000);assert.deepEqual(settle(next,market,now+365*DAY),next);assert.equal(summary(next,market,now+365*DAY).profit,0)});
test('migration archives bills and preserves money, deposits, orders and historical payroll',()=>{const s=create();s.config.experience=undefined;s.config.reserve=500;s.config.expenses={rent:3000};s.bills=[{id:'old',amount:3000,paid:false}];s.holdings={AAPL:{qty:1,lastEur:100}};s.orders=[{id:'queued',asset:'AAPL',side:'buy',amount:1000,createdAt:now}];const before=structuredClone(s),next=investmentAccount(s,now);assert.deepEqual(s,before);assert.equal(next.cash,before.cash);assert.deepEqual(next.holdings,before.holdings);assert.deepEqual(next.orders,before.orders);assert.equal(next.householdArchive.bills.length,1);assert.equal(next.bills.length,0);assert.deepEqual(next.config.expenses,{});assert.equal(investmentAccount(next,now),next);assert.throws(()=>run(next,{type:'pay_all'}),/solo usa/)});
test('all stocks and funds can unlock; purchases need a reason and execute only on later prices',()=>{let s=create();for(const c of CATALOG.filter(c=>c.group!=='legacy')){s=run(s,{type:'lesson',asset:c.id,answer:c.answer});assert.ok(s.lessons.includes(c.id))}assert.throws(()=>run(s,{type:'buy',asset:'NVDA',amount:1}),/frase/);s=run(s,{type:'buy',asset:'NVDA',amount:1,reason:'Quiero aprender cómo funcionan los chips.'});assert.equal(s.holdings.NVDA,undefined);assert.equal(s.reflections.length,1);const later={...market,prices:{...market.prices,NVDA:{eur:125,at:now+DAY,fetchedAt:now+DAY}}};s=settle(s,later,now+DAY);assert.equal(s.holdings.NVDA.qty,.08);assert.equal(summary(s,later,now+DAY).profit,0);assert.throws(()=>run(s,{type:'buy',asset:'BTC',amount:1,reason:'Quiero comprar otra cosa.'}),/Instrumento/)});
test('hypothetical compounding handles zero and negative returns without touching market data',()=>{assert.equal(compoundProjection(100,10,1,0).value,220);assert.ok(compoundProjection(100,0,2,5).value>110);assert.ok(compoundProjection(100,0,2,-10).value<100);assert.throws(()=>compoundProjection(100,10,0,5));assert.throws(()=>compoundProjection(100,10,10,100));});

test('initial grant is fixed; parent top-ups are protected, idempotent and not profits',()=>{let s=create();assert.equal(s.config.initial,1000000);assert.equal(summary(s,market,now).profit,0);const a={type:'employer',decision:'bonus',amount:50,reason:'Aprender juntos',requestId:'parent-extra-001'};assert.throws(()=>action(s,market,a,now),/PIN parental/);s=action(s,market,a,now,{parent:true});assert.equal(s.cash,1050000);assert.equal(summary(s,market,now).profit,0);assert.deepEqual(action(s,market,a,now,{parent:true}),s);assert.throws(()=>run(s,{...a,requestId:'invalid-negative',amount:-1}),/importe/);assert.equal(settle(s,market,Date.parse('2026-11-30T12:00Z')).cash,1060000)});
